    List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Study of literature, writing, and communication." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events, societies, and civilizations." },
            new() { Id = 6, Name = "Biology", Abbreviation = "BIO", Description = "Study of living organisms and life processes." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Email = "s.chen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 40 papers in top-tier venues and holds three patents in natural language processing." },
            new() { Id = 2, Name = "Dr. James Rodriguez", Title = "Professor", Email = "j.rodriguez@university.edu", Bio = "Dr. Rodriguez has been teaching calculus and analysis for over 20 years. He received the University Distinguished Teaching Award in 2023." },
            new() { Id = 3, Name = "Dr. Emily Watson", Title = "Assistant Professor", Email = "e.watson@university.edu", Bio = "Dr. Watson researches quantum computing and condensed matter physics. She completed her postdoc at CERN before joining the department." },
            new() { Id = 4, Name = "Prof. Michael Torres", Title = "Professor", Email = "m.torres@university.edu", Bio = "Prof. Torres is a published novelist and literary critic. His latest book on postmodern American fiction was a finalist for the National Book Critics Circle Award." },
            new() { Id = 5, Name = "Dr. Lisa Park", Title = "Associate Professor", Email = "l.park@university.edu", Bio = "Dr. Park specializes in medieval European history with a focus on the Crusades. She leads the university's Medieval Studies program." },
            new() { Id = 6, Name = "Dr. Robert Kim", Title = "Professor", Email = "r.kim@university.edu", Bio = "Dr. Kim researches molecular biology and genetics. He runs a lab focused on CRISPR gene-editing applications in medicine." },
            new() { Id = 7, Name = "Dr. Anna Novak", Title = "Assistant Professor", Email = "a.novak@university.edu", Bio = "Dr. Novak specializes in data structures and software engineering. She previously worked at a major tech company before transitioning to academia." },
            new() { Id = 8, Name = "Dr. David Liu", Title = "Associate Professor", Email = "d.liu@university.edu", Bio = "Dr. Liu focuses on cybersecurity and network systems. He advises multiple government agencies on information security policy." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior programming experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Tech Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes weekly programming assignments in Java.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Room = "Tech Hall 305", DepartmentId = 1, InstructorId = 7, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 340", Title = "Artificial Intelligence", Description = "Covers core AI topics including search algorithms, knowledge representation, probabilistic reasoning, machine learning fundamentals, and neural networks. Students complete a capstone project building an intelligent agent.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Hall 401", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "CS 380", Title = "Cybersecurity Fundamentals", Description = "Introduction to information security principles, cryptography, network security, vulnerability analysis, and ethical hacking. Hands-on labs using industry-standard security tools.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Tech Hall 110", DepartmentId = 1, InstructorId = 8, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 38 },

            // Mathematics
            new() { Id = 5, Code = "MATH 151", Title = "Calculus I", Description = "Limits, continuity, derivatives of algebraic and transcendental functions, applications of the derivative, and an introduction to integration. Prerequisite: placement exam or MATH 110.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Science Center 102", DepartmentId = 2, InstructorId = 2, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 6, Code = "MATH 250", Title = "Linear Algebra", Description = "Systems of linear equations, matrix algebra, vector spaces, linear transformations, eigenvalues, and applications to geometry and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Science Center 205", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 42 },

            // Physics
            new() { Id = 7, Code = "PHYS 201", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Co-requisite: MATH 151 or equivalent.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", Room = "Physics Building 101", DepartmentId = 3, InstructorId = 3, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 8, Code = "PHYS 350", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave-particle duality, the Schrödinger equation, hydrogen atom, angular momentum, and spin. Prerequisite: PHYS 202 and MATH 252.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Physics Building 303", DepartmentId = 3, InstructorId = 3, IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 22 },

            // English
            new() { Id = 9, Code = "ENG 101", Title = "College Writing", Description = "Develop critical reading and academic writing skills. Students write multiple essays exploring argumentation, analysis, and research-based writing.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Humanities 210", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = 10, Code = "ENG 280", Title = "American Literature Survey", Description = "A chronological survey of American literature from the colonial period to the present, including works by Hawthorne, Whitman, Dickinson, Fitzgerald, Morrison, and others.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Room = "Humanities 315", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 28 },

            // History
            new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "A global survey of human civilizations from prehistory through the late medieval period, covering Mesopotamia, Egypt, Greece, Rome, China, the Islamic world, and medieval Europe.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Room = "Liberal Arts 120", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 72 },
            new() { Id = 12, Code = "HIST 320", Title = "The Crusades", Description = "An in-depth study of the Crusading movement from 1095 to 1291, examining military campaigns, cultural exchange, religious motivations, and lasting impacts on East-West relations.", Credits = 3, Schedule = "Thu 6:00–8:50 PM", Room = "Liberal Arts 205", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 18 },

            // Biology
            new() { Id = 13, Code = "BIO 101", Title = "Introduction to Biology", Description = "Fundamental principles of biology including cell structure, genetics, evolution, ecology, and biodiversity. Includes a weekly lab.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 2:00–4:50 PM", Room = "Life Sciences 101", DepartmentId = 6, InstructorId = 6, IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 78 },
            new() { Id = 14, Code = "BIO 310", Title = "Molecular Biology and Genetics", Description = "Advanced study of DNA replication, gene expression, regulation, and modern genetic engineering techniques including CRISPR. Prerequisite: BIO 201.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Life Sciences 310", DepartmentId = 6, InstructorId = 6, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },
        };

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            query = query.Where(c => c.Credits == credits.Value);
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        if (course is null)
            return false;

        // In a real app, this would persist to a database
        return true;
    }
}

