@using UniversityCourseCatalog.Models

<div class="card h-100 shadow-sm featured-course-card">
    <div class="card-body d-flex flex-column">
        <span class="badge bg-primary mb-2 align-self-start">@Course.Code</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted small flex-grow-1">@Truncate(Course.Description, 120)</p>
        <div class="d-flex justify-content-between align-items-center mt-2">
            <span class="text-muted small">
                <strong>@Course.Credits</strong> credits &middot; @Course.Department.Abbreviation
            </span>
            <a href="@($"courses/{Course.Id}")" class="btn btn-outline-primary btn-sm">View Details</a>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using UniversityCourseCatalog.Models

<div class="card mb-4">
    <div class="card-body">
        <div class="row g-3">
            <div class="col-md-5">
                <label for="search" class="form-label fw-semibold">Search</label>
                <input id="search" type="text" class="form-control" placeholder="Course name, code, or instructor…"
                       @bind="SearchTerm" @bind:event="oninput" @bind:after="OnFilterChanged" />
            </div>
            <div class="col-md-4">
                <label for="department" class="form-label fw-semibold">Department</label>
                <select id="department" class="form-select" @bind="SelectedDepartmentId" @bind:after="OnFilterChanged">
                    <option value="0">All Departments</option>
                    @foreach (var dept in Departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-3">
                <label for="credits" class="form-label fw-semibold">Credits</label>
                <select id="credits" class="form-select" @bind="SelectedCredits" @bind:after="OnFilterChanged">
                    <option value="0">Any</option>
                    <option value="3">3 Credits</option>
                    <option value="4">4 Credits</option>
                </select>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = new();

    [Parameter]
    public EventCallback<(string? SearchTerm, int? DepartmentId, int? Credits)> FiltersChanged { get; set; }

    private string? SearchTerm { get; set; }
    private int SelectedDepartmentId { get; set; }
    private int SelectedCredits { get; set; }

    private async Task OnFilterChanged()
    {
        int? deptId = SelectedDepartmentId > 0 ? SelectedDepartmentId : null;
        int? credits = SelectedCredits > 0 ? SelectedCredits : null;
        await FiltersChanged.InvokeAsync((SearchTerm, deptId, credits));
    }
}

