@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container-fluid">
    <div class="text-center py-4">
        <h1 class="display-5 fw-bold">University Course Catalog</h1>
        <p class="lead text-muted">Explore our courses and find the right fit for your academic journey.</p>
        <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
        <a href="enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
    </div>

    <hr />

    <section class="my-4">
        <h2 class="mb-3">Featured Courses</h2>
        <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
            @foreach (var course in _featuredCourses)
            {
                <div class="col">
                    <FeaturedCourseCard Course="course" />
                </div>
            }
        </div>
    </section>

    <hr />

    <section class="my-4">
        <h2 class="mb-3">Departments</h2>
        <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
            @foreach (var dept in _departments)
            {
                <div class="col">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <span class="badge bg-secondary mb-2">@dept.Abbreviation</span>
                            <p class="card-text small text-muted">@dept.Description</p>
                            <a href="@($"courses?departmentId={dept.Id}")" class="btn btn-outline-secondary btn-sm">
                                View Courses →
                            </a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@rendermode InteractiveServer
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>Course Catalog — Browse Courses</PageTitle>

<div class="container-fluid">
    <h1 class="mb-3">Course Catalog</h1>

    <CourseFilters Departments="_departments" FiltersChanged="HandleFiltersChanged" />

    <div class="d-flex justify-content-between align-items-center mb-3">
        <p class="text-muted mb-0">
            Showing <strong>@_filteredCourses.Count</strong> course@(_filteredCourses.Count != 1 ? "s" : "")
        </p>
    </div>

    @if (_filteredCourses.Count == 0)
    {
        <div class="alert alert-info">
            No courses match your search criteria. Try adjusting your filters.
        </div>
    }
    else
    {
        @foreach (var course in _filteredCourses)
        {
            <CourseCard Course="course" />
        }
    }
</div>

@code {
    private List<Department> _departments = new();
    private List<Course> _filteredCourses = new();

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
