toolArgs.file_text:
@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<div class="container-fluid">
    <h1 class="mb-3">Enrollment Request</h1>
    <p class="text-muted">Fill out the form below to submit an enrollment request. You will receive a confirmation once your request is processed.</p>

    <div class="row">
        <div class="col-lg-8">
            <div class="card">
                <div class="card-body">
                    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                        <AntiforgeryToken />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                            <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                            <ValidationMessage For="() => Model.StudentName" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                            <InputText id="studentId" class="form-control" placeholder="e.g., CS123456" @bind-Value="Model.StudentId" />
                            <ValidationMessage For="() => Model.StudentId" />
                            <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                                <option value="0">— Select a course —</option>
                                @foreach (var course in _courses)
                                {
                                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => Model.CourseId" />
                        </div>

                        <div class="mb-3">
                            <label for="comments" class="form-label">Comments (optional)</label>
                            <InputTextArea id="comments" class="form-control" rows="3" @bind-Value="Model.Comments" />
                            <ValidationMessage For="() => Model.Comments" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>

                        <DataAnnotationsValidator />
                    </form>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> _courses = new();

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollmentRequest(Model);
        if (success)
        {
            NavigationManager.NavigateTo($"enroll/confirmation?courseId={Model.CourseId}&studentName={Uri.EscapeDataString(Model.StudentName)}");
        }
    }

    [Inject]
    private NavigationManager NavigationManager { get; set; } = default!;
}

@page "/enroll/confirmation"
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Confirmed — University Course Catalog</PageTitle>

<div class="container-fluid">
    <div class="text-center py-5">
        <div class="mb-4">
            <span class="display-1">✓</span>
        </div>
        <h1 class="mb-3">Enrollment Request Submitted</h1>
        <p class="lead text-muted">
            Thank you, <strong>@StudentName</strong>! Your enrollment request
            @if (_course is not null)
            {
                <text> for <strong>@_course.Code — @_course.Title</strong></text>
            }
            has been submitted successfully.
        </p>
        <p class="text-muted">You will receive a confirmation email once your request is reviewed by the registrar's office.</p>

        <div class="mt-4">
            <a href="courses" class="btn btn-primary me-2">Browse More Courses</a>
            <a href="" class="btn btn-outline-secondary">Return Home</a>
        </div>
    </div>
</div>

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [SupplyParameterFromQuery]
    public string? StudentName { get; set; }

    private UniversityCourseCatalog.Models.Course? _course;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue)
        {
            _course = CatalogService.GetCourse(CourseId.Value);
        }
    }
}

